"use client";
import { useState } from "react";
import { Shell, Stats, Banner } from "@/components/term";
import { freshPattern, randInt, useBest, submitScore } from "@/lib/levels";

function toggle(b: boolean[], n: number, i: number) {
  const nb = [...b];
  const r = Math.floor(i / n), c = i % n;
  for (const [dr, dc] of [[0, 0], [1, 0], [-1, 0], [0, 1], [0, -1]]) {
    const nr = r + dr, nc = c + dc;
    if (nr >= 0 && nc >= 0 && nr < n && nc < n) nb[nr * n + nc] = !nb[nr * n + nc];
  }
  return nb;
}

// Generated by applying random presses to a dark board => always solvable.
function makeLevel(level: number) {
  const n = Math.min(3 + Math.floor((level - 1) / 2), 7);
  const presses = Math.min(level + 2, n * n - 1);
  return freshPattern("lights", () => {
    let b: boolean[] = Array(n * n).fill(false);
    const used = new Set<number>();
    while (used.size < presses) used.add(randInt(n * n));
    used.forEach((i) => { b = toggle(b, n, i); });
    if (b.every((x) => !x)) b = toggle(b, n, 0);
    return { n, b, par: presses };
  }, (x) => x.b.map((v) => (v ? 1 : 0)).join(""));
}

export default function LightsOut() {
  const [level, setLevel] = useState(1);
  const [st, setSt] = useState<{ n: number; b: boolean[]; par: number } | null>(null);
  const [initial, setInitial] = useState<boolean[]>([]);
  const [moves, setMoves] = useState(0);
  const [won, setWon] = useState(false);
  const [best, report] = useBest("lights");

  function start(l: number) {
    const lv = makeLevel(l);
    setSt(lv);
    setInitial(lv.b);
    setMoves(0);
    setWon(false);
  }

  function press(i: number) {
    if (!st || won) return;
    const nb = toggle(st.b, st.n, i);
    setSt({ ...st, b: nb });
    setMoves((m) => m + 1);
    if (nb.every((x) => !x)) {
      setWon(true);
      report(level);
      submitScore("lights", level, { moves: moves + 1 });
    }
  }

  const size = st ? Math.min(60, Math.floor(320 / st.n)) : 60;

  return (
    <Shell path="/games/lights" title="lights out" help="pressing a cell flips it and its 4 neighbours. switch every light off. each board is new and guaranteed solvable.">
      <Stats items={[["level", level], ["moves", moves], ["par", st?.par ?? "-"], ["lit", st ? st.b.filter(Boolean).length : "-"], ["best", best]]} />
      {!st ? (
        <button className="btn mt-4" onClick={() => start(1)}>start</button>
      ) : (
        <>
          <div className="mt-4 inline-grid gap-1" style={{ gridTemplateColumns: `repeat(${st.n}, ${size}px)` }}>
            {st.b.map((on, i) => (
              <button key={`${level}-${i}`} className={`cell ${on ? "on" : ""}`} style={{ width: size, height: size }} onClick={() => press(i)}>
                {on ? "[#]" : "[ ]"}
              </button>
            ))}
          </div>
          <div className="mt-2">
            <button className="btn" onClick={() => { setSt({ ...st, b: initial }); setMoves(0); }}>reset board</button>
          </div>
        </>
      )}
      {won && (
        <Banner title={`level ${level} dark`} lines={[`${moves} moves (par ${st?.par})`]} action="next level" onAction={() => { const n = level + 1; setLevel(n); start(n); }} />
      )}
    </Shell>
  );
}
